{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03","C08","C12","C17","C21","C32","C35","C36","C38","C42","C43","C44"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03","C12","C17","C32","C21","C08"],
  "claims": [
    {
      "claim": "The query is a C-aryl glycoside SGLT2 inhibitor with a bridged dioxabicyclooctane core, closely paralleled by tofogliflozin; tofogliflozin has absolute oral bioavailability of about 97.5–98% in humans and 97% in a summary table, and a tofogliflozin-associated monkey record reports 85% F, all well above the 20% threshold.",
      "card_ids": ["C03","C12","C17","C32","C21"]
    },
    {
      "claim": "A tofogliflozin record reports high bioavailability after a single 20 mg oral dose, consistent with the absolute bioavailability measurements.",
      "card_ids": ["C08"]
    },
    {
      "claim": "New L3 oral-exposure records for dapagliflozin, which shares the query's 4-chloro-3-(4-ethoxybenzyl)phenyl aglycone, show rapid absorption (median Tmax 0.75 h; Tmax ≤1.5 h) and comparable AUC between fed and fasted states and in hepatic impairment, supporting good oral absorption and exposure; no L3 record reports low F or F <20%.",
      "card_ids": ["C35","C36","C38","C42","C43","C44"]
    },
    {
      "claim": "Empagliflozin Tmax records in the same SGLT2 class are consistent with rapid absorption but are less structurally relevant; ketoconazole Cmax records are structurally unrelated and do not bear on the query.",
      "card_ids": ["C37","C40","C41","C46","C39","C45"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C35","C36","C38","C42","C43","C44"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C37","C40","C41","C46"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C39","C45"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present; the decision relies on structural transfer from tofogliflozin and class exposure data.",
    "The tofogliflozin absolute-F records do not explicitly report a fasted condition; fasted-state transfer is inferred, though dapagliflozin L3 records show comparable AUC in fed vs fasted states.",
    "L3 dapagliflozin/empagliflozin records report Tmax and AUC comparability but not absolute F values for those molecules or the query.",
    "The query physicochemical prior is mixed (high TPSA/HBD), but no direct permeability or solubility data are supplied; this is not affirmative evidence of F <20%.",
    "Posaconazole fasted-state variability records are structurally unrelated and not threshold-specific."
  ],
  "decision_summary": "High: the query's C-aryl glycoside SGLT2 inhibitor scaffold is closely paralleled by tofogliflozin (absolute F ~97.5–98% in humans, 97% summary, 85% monkey), and new L3 dapagliflozin exposure records sharing the same aglycone show rapid absorption and comparable fed/fasted AUC, supporting F >=20%. No affirmative F <20% evidence is present; confidence raised to high."
}

